package local.z6panel;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
import java.io.*;import java.util.*;import java.util.concurrent.*;
import org.json.JSONObject;

/** HOME owns one visible bitmap. Photos and image work never run in the overlay. */
final class HomeWallpaper {
 private final Activity activity;private final ImageView image;private final View shade;private final Handler ui=new Handler(Looper.getMainLooper());
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"Z6-home-wallpaper"),new ThreadPoolExecutor.DiscardPolicy());
 private WallpaperMediaObserver mediaObserver;private final SharedPreferences prefs;private Bitmap bitmap;private volatile WallpaperOnline online;private volatile boolean active;private volatile int generation;private volatile String loaded="";private boolean reduced;private String warning="",effectiveQuality="",fit="",lastNotice="";
 HomeWallpaper(Activity a,ImageView v,View s){activity=a;image=v;shade=s;prefs=a.getSharedPreferences("panel",0);worker.allowCoreThreadTimeOut(true);mediaObserver=new WallpaperMediaObserver(a,()->{mediaRevision++;preparedConfig="";if(active){loaded="";maintainThenLoad(generation);}});}
 private boolean prefetchPending;private Runnable pendingPrefetch;
 private int mediaRevision,preparedRevision,fastResumes;private volatile int maintenanceRuns;
 private String preparedConfig="",preparedDay="";private long preparedAt,nextCheckAt;
 private String configuration(){return prefs.getString("wallpaper_mode","original")+"|"+prefs.getString("wallpaper_photo","")+"|"+prefs.getString("wallpaper_quality","auto")+"|"+prefs.getInt("wallpaper_minutes",30)+"|"+prefs.getBoolean(WallpaperSelection.ALL,true)+"|"+new TreeSet<>(prefs.getStringSet(WallpaperSelection.IDS,Collections.emptySet()))+"|"+prefs.getInt("wallpaper_daily_hours",0)+"|"+prefs.getLong("wallpaper_daily_epoch",0)+"|"+prefs.getInt("wallpaper_daily_base",0)+"|"+WallpaperImages.screenWidth(activity)+"x"+WallpaperImages.screenHeight(activity)+"|"+TimeZone.getDefault().getID()+"|"+reduced;}
 private void prepared(String config,int revision){if(revision==mediaRevision&&config.equals(configuration())){preparedConfig=config;preparedRevision=revision;preparedDay=WallpaperOnline.today();preparedAt=SystemClock.elapsedRealtime();}}
 private void maintainThenLoad(final int token){worker.execute(()->{if(!active||token!=generation)return;maintenanceRuns++;WallpaperOnline.maintain(activity);ui.post(()->{if(active&&token==generation)load(false);});});}
 private int renderedCount,releaseCount,firstFrameFallbacks,coalescedFirstResumes;
 private String firstDrawConfig="";private int firstDrawRevision;
 private ViewTreeObserver.OnPreDrawListener firstDraw;
 private final Runnable firstDrawTimeout=()->{firstFrameFallbacks++;finishFirstDraw();};
 private void awaitFirstDraw(){if(bitmap!=null||prefs.getString("wallpaper_mode","original").equals("original")||firstDraw!=null)return;firstDrawConfig=configuration();firstDrawRevision=mediaRevision;firstDraw=()->false;image.getViewTreeObserver().addOnPreDrawListener(firstDraw);ui.postDelayed(firstDrawTimeout,renderedCount==0?2500:1000);}
 private void finishFirstDraw(){ui.removeCallbacks(firstDrawTimeout);if(firstDraw!=null){if(image.getViewTreeObserver().isAlive())image.getViewTreeObserver().removeOnPreDrawListener(firstDraw);firstDraw=null;image.invalidate();}}
 private final Runnable advance=()->load(true);
 void nextForShell(){if(active)load(true);}
 void resume(){if(active&&firstDraw!=null&&firstDrawRevision==mediaRevision&&firstDrawConfig.equals(configuration())){coalescedFirstResumes++;return;}reduced=WallpaperImages.lowRam(activity);active=true;generation++;ui.removeCallbacks(advance);mediaObserver.start();final int token=generation;long now=System.currentTimeMillis();
  // Repeated HOME intents do not change an already validated, still-visible image.
  // The one-minute bound is checked on entry; it adds no periodic work.
  if((bitmap!=null||prefs.getString("wallpaper_mode","original").equals("original"))&&configuration().equals(preparedConfig)&&preparedRevision==mediaRevision&&preparedDay.equals(WallpaperOnline.today())&&SystemClock.elapsedRealtime()-preparedAt<60000&&(nextCheckAt==0||now<nextCheckAt)){fastResumes++;if(prefetchPending)queuePrefetch(token);if(nextCheckAt>0)ui.postDelayed(advance,Math.max(1,nextCheckAt-now));return;}
  if(bitmap==null){awaitFirstDraw();load(false,false);}maintainThenLoad(token);
 }
 // A paused HOME can still be visible during a new intent or above/below TV settings.
 // Stop work now; release its pixels only once the activity is actually hidden.
 void pause(){active=false;generation++;ui.removeCallbacks(advance);if(pendingPrefetch!=null)ui.removeCallbacks(pendingPrefetch);worker.getQueue().clear();if(online!=null)online.cancel();finishFirstDraw();}
 void stop(){pause();mediaObserver.stop();clear();}
 void destroy(){stop();worker.shutdownNow();}
 void trim(){reduced=true;generation++;worker.getQueue().clear();clear();if(active)load(false);}
 private void clear(){image.setImageDrawable(null);image.setBackgroundColor(Color.TRANSPARENT);shade.setVisibility(View.GONE);if(bitmap!=null){bitmap.recycle();bitmap=null;releaseCount++;}loaded="";preparedConfig="";nextCheckAt=0;prefetchPending=false;warning="";effectiveQuality="";fit="";}
 private void load(boolean next){load(next,true);}
 private void load(boolean next,boolean refresh){ui.removeCallbacks(advance);if(!active)return;final String config=configuration();final int revision=mediaRevision;String mode=prefs.getString("wallpaper_mode","original");if(mode.equals("original")){clear();if(refresh)prepared(config,revision);finishFirstDraw();return;}final int token=generation;final String requested=prefs.getString("wallpaper_quality","auto");
  final boolean firstLocal=!refresh&&firstDraw!=null;
  worker.execute(()->{int priority=android.os.Process.getThreadPriority(android.os.Process.myTid());if(firstLocal)try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_DEFAULT);}catch(SecurityException ignored){}WallpaperSource file=null;try{
   WallpaperStore store=new WallpaperStore(activity);if(!active||token!=generation)return;
   if(mode.equals("daily")){online=new WallpaperOnline();if(!active||token!=generation){online.cancel();return;}if(refresh)try{online.update(activity,false);}catch(Exception ignored){}if(!active||token!=generation)return;file=WallpaperOnline.file(activity);}

   else{List<WallpaperStore.Photo> list=store.photos();if(mode.equals("slideshow")){list=WallpaperSelection.eligible(prefs,list);if(list.isEmpty()){prefs.edit().putString("wallpaper_mode","original").remove("wallpaper_slide_id").apply();ui.post(()->{if(active&&token==generation){clear();finishFirstDraw();Toast.makeText(activity,"Presentación detenida: no quedan fotos elegidas",Toast.LENGTH_LONG).show();}});return;}}if(!list.isEmpty()){String id=prefs.getString(mode.equals("slideshow")?"wallpaper_slide_id":"wallpaper_photo","");int index=-1;for(int i=0;i<list.size();i++)if(list.get(i).id.equals(id))index=i;if(index<0&&mode.equals("photo"))list=Collections.emptyList();else if(index<0)index=0;if(!list.isEmpty()){if(next&&mode.equals("slideshow"))index=(index+1)%list.size();WallpaperStore.Photo photo=list.get(index);file=photo.file;if(mode.equals("slideshow"))prefs.edit().putString("wallpaper_slide_id",photo.id).apply();}}}
   if(!active||token!=generation)return;final String signature=file==null?"":file.getName()+"|"+file.lastModified()+"|"+WallpaperImages.screenWidth(activity)+"x"+WallpaperImages.screenHeight(activity)+"|"+requested+"|"+reduced;
   final WallpaperImages.Rendered result=file==null||signature.equals(loaded)?null:WallpaperImages.render(activity,file,requested,reduced);
   ui.post(()->{if(!active||token!=generation){if(result!=null)result.bitmap.recycle();return;}if(result!=null){Bitmap old=bitmap;bitmap=result.bitmap;renderedCount++;image.setScaleType(result.contain?ImageView.ScaleType.FIT_CENTER:ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(WallpaperImages.DARK);image.setImageBitmap(bitmap);shade.setVisibility(View.VISIBLE);loaded=signature;warning=result.warning;effectiveQuality=result.quality;fit=result.contain?"contain":"cover";if(old!=null)old.recycle();if(warning.startsWith("Calidad reducida")&&!warning.equals(lastNotice)){lastNotice=warning;Toast.makeText(activity,warning,Toast.LENGTH_LONG).show();}}else if(signature.isEmpty())clear();finishFirstDraw();schedule(mode);if(refresh)prepared(config,revision);if(refresh&&mode.equals("daily")&&WallpaperOnline.rotation(activity)>0){prefetchPending=true;queuePrefetch(token);}});
  }catch(Exception failure){ui.post(()->{if(active&&token==generation){warning="Se conserva el fondo anterior: "+failure.getMessage();finishFirstDraw();schedule(mode);}});}finally{if(firstLocal)try{android.os.Process.setThreadPriority(priority);}catch(SecurityException ignored){}}});
 }
 private void queuePrefetch(final int token){if(pendingPrefetch!=null)ui.removeCallbacks(pendingPrefetch);pendingPrefetch=()->{if(active&&token==generation)worker.execute(()->{if(!active||token!=generation)return;online=new WallpaperOnline();try{online.prefetch(activity);ui.post(()->{if(active&&token==generation)prefetchPending=false;});}catch(Exception ignored){}});};ui.postDelayed(pendingPrefetch,1200);}
 private void schedule(String mode){if(!active)return;nextCheckAt=0;if(mode.equals("slideshow")){long delay=Math.max(5,prefs.getInt("wallpaper_minutes",30))*60000L;nextCheckAt=System.currentTimeMillis()+delay;ui.postDelayed(advance,delay);}else if(mode.equals("daily")){long midnight;java.util.Calendar day=java.util.Calendar.getInstance();day.add(java.util.Calendar.DAY_OF_YEAR,1);day.set(java.util.Calendar.HOUR_OF_DAY,0);day.set(java.util.Calendar.MINUTE,0);day.set(java.util.Calendar.SECOND,0);day.set(java.util.Calendar.MILLISECOND,0);midnight=Math.max(1000,day.getTimeInMillis()-System.currentTimeMillis());long rotate=WallpaperOnline.nextDelay(activity);long delay=rotate<0?midnight:Math.min(midnight,rotate);nextCheckAt=System.currentTimeMillis()+delay;ui.postDelayed(advance,delay);}}
 String inspect(){int[] location=new int[2];image.getLocationOnScreen(location);return "{\"coalescedFirstResumes\":"+coalescedFirstResumes+",\"resumeReady\":"+!preparedConfig.isEmpty()+",\"fastResumes\":"+fastResumes+",\"maintenanceRuns\":"+maintenanceRuns+",\"firstDrawPending\":"+(firstDraw!=null)+",\"firstFrameFallbacks\":"+firstFrameFallbacks+",\"renders\":"+renderedCount+",\"releases\":"+releaseCount+",\"viewX\":"+location[0]+",\"viewY\":"+location[1]+",\"viewWidth\":"+image.getWidth()+",\"viewHeight\":"+image.getHeight()+",\"active\":"+active+",\"loaded\":"+(bitmap!=null)+",\"bytes\":"+(bitmap==null?0:bitmap.getAllocationByteCount())+",\"width\":"+(bitmap==null?0:bitmap.getWidth())+",\"height\":"+(bitmap==null?0:bitmap.getHeight())+",\"key\":"+JSONObject.quote(loaded)+",\"warning\":"+JSONObject.quote(warning)+",\"effectiveQuality\":"+JSONObject.quote(effectiveQuality)+",\"fit\":"+JSONObject.quote(fit)+",\"scheduled\":"+(active&&prefs.getString("wallpaper_mode","original").equals("slideshow"))+"}";}
}
